// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/addons.ts`. Edit the source and run `just generate`.
// The optional steps of the add-ons that are installed and not disabled.
// This file names each add-on as text and imports nothing from it.
// Claude Code lists a plugin as `"<name>@<marketplace>": true` in `enabledPlugins` when it installs it, and `false` when the user disables it.

import { ADDON_CODEGRAPH } from "../prompts.ts";
import { isObject, type Json } from "./merge.ts";

/** The text of each add-on step, by plugin name. */
const STEPS: Record<string, string> = {
  "claudetto-codegraph": ADDON_CODEGRAPH,
};

/**
 * The steps of the add-ons that `settings` list as enabled.
 * `settings` are the parsed files in the order user, project, local, and a later file wins, as in Claude Code.
 */
export const addonSteps = (settings: Json[]): string[] => {
  const state = new Map(
    settings.flatMap((file) => {
      const plugins = file["enabledPlugins"];
      return isObject(plugins)
        ? Object.entries(plugins).map(
            ([id, on]) => [id.split("@")[0], on === true] as const,
          )
        : [];
    }),
  );
  return Object.entries(STEPS)
    .filter(([name]) => state.get(name))
    .map(([, text]) => text);
};
